import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.1lR7qgqY.js";const m=JSON.parse('{"title":"M8 代理與治理","description":"","frontmatter":{},"headers":[],"relativePath":"build/m8-agent-governance.md","filePath":"build/m8-agent-governance.md","lastUpdated":null}'),r={name:"build/m8-agent-governance.md"};function n(o,a,s,h,p,c){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="m8-代理與治理" tabindex="-1">M8 代理與治理 <a class="header-anchor" href="#m8-代理與治理" aria-label="Permalink to &quot;M8 代理與治理&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ◇ 進階</li><li>狀態: 可閱讀 (M8.2 至 M8.5 僅有大綱)</li><li>資料基準日: 2026-10-26</li></ul></div><p><strong>結論</strong>: 代理讓模型自己決定下一步要呼叫哪個工具, 所以每個動作都要在模型之外再檢查一次. 本手冊的做法是: LangGraph 負責流程控制, OPA 負責政策判定, 讀取不可信內容的工作交給沒有工具的隔離模型.</p><p><strong>這一塊在圖上的位置</strong>: VM 控制區 (LangGraph, OPA) 與 VM 隔離區 (自建程式 + 本地模型). <strong>前置模組</strong>: M7. <strong>完成後的狀態</strong>: 代理能處理多步驟任務, 寫入與刪除需要人工核准, 異常時自動切斷.</p><h2 id="m8-1-langgraph-當函式庫用-不用平台版" tabindex="-1">M8.1 LangGraph: 當函式庫用, 不用平台版 <a class="header-anchor" href="#m8-1-langgraph-當函式庫用-不用平台版" aria-label="Permalink to &quot;M8.1 LangGraph: 當函式庫用, 不用平台版&quot;">​</a></h2><ul><li>程式庫採 MIT 授權, 可完全地端執行, 無商業限制.</li><li>LangGraph Platform 已改名為 LangSmith Deployment. 依 LangChain 官方 CLI 文件, <code>langgraph up</code> 啟動的 Agent Server 在正式環境需要授權金鑰.</li><li>因此本手冊建議把 LangGraph 當函式庫, 嵌入自己的 FastAPI 或腳本 (信心: 高).</li><li>需要理解狀態圖, 檢查點與節點等概念, 對初階讀者偏陡 (信心: 中, 屬推論).</li></ul><h2 id="m8-2-政策引擎-opa" tabindex="-1">M8.2 政策引擎 (OPA) <a class="header-anchor" href="#m8-2-政策引擎-opa" aria-label="Permalink to &quot;M8.2 政策引擎 (OPA)&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>預設拒絕; 關鍵資產清單; 對外連線白名單; 單次工具配額</li><li>LangGraph 每個工具呼叫前先查詢 OPA, 違規則擋下或轉人工核准</li><li>政策以檔案管理, 納入版本控制</li></ul><h2 id="m8-3-隔離模型-雙-llm-模式" tabindex="-1">M8.3 隔離模型 (雙 LLM 模式) <a class="header-anchor" href="#m8-3-隔離模型-雙-llm-模式" aria-label="Permalink to &quot;M8.3 隔離模型 (雙 LLM 模式)&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>讀取 log, 郵件, 外部情資等不可信內容的模型不給任何工具</li><li>只輸出固定欄位的 JSON, 由程式檢查格式與長度</li><li>擋不住的情況: 惡意值放進合法欄位, 須靠 OPA 的關鍵資產清單</li></ul><h2 id="m8-4-人工核准-斷路器與配額" tabindex="-1">M8.4 人工核准, 斷路器與配額 <a class="header-anchor" href="#m8-4-人工核准-斷路器與配額" aria-label="Permalink to &quot;M8.4 人工核准, 斷路器與配額&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>依動作能否回復分級: 唯讀, 可回復, 影響範圍大, 不可回復; 不可回復者一律人工核准</li><li>斷路器只切斷異常的工具路徑, kill switch 留作最後防線</li></ul><h2 id="m8-5-驗收測試" tabindex="-1">M8.5 驗收測試 <a class="header-anchor" href="#m8-5-驗收測試" aria-label="Permalink to &quot;M8.5 驗收測試&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>以內含提示注入的測試資料驗證: 有害動作一律擋下或轉人工核准</li><li>確認每次政策判定都留下紀錄</li></ul>',18)])])}const u=l(r,[["render",n]]);export{m as __pageData,u as default};
